def f(inp):
    h=len(inp); w=len(inp[0])
    L=[r[:w//2] for r in inp]; R=[r[w//2:] for r in inp]
    def cc(g,bg):
        seen=set(); res=[]; hh=len(g); ww=len(g[0])
        for i in range(hh):
            for j in range(ww):
                if g[i][j]!=bg and (i,j) not in seen:
                    s=[(i,j)]; st=[(i,j)]; seen.add((i,j)); col=g[i][j]
                    while st:
                        a,b=st.pop()
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            na,nb=a+da,b+db
                            if 0<=na<hh and 0<=nb<ww and g[na][nb]==col and (na,nb) not in seen:
                                seen.add((na,nb)); s.append((na,nb))
                    res.append(s)
        return res
    def zcomps(g):
        seen=set(); res=[]; hh=len(g); ww=len(g[0])
        for i in range(hh):
            for j in range(ww):
                if g[i][j]==0 and (i,j) not in seen:
                    s=[(i,j)]; st=[(i,j)]; seen.add((i,j))
                    while st:
                        a,b=st.pop()
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            na,nb=a+da,b+db
                            if 0<=na<hh and 0<=nb<ww and g[na][nb]==0 and (na,nb) not in seen:
                                seen.add((na,nb)); s.append((na,nb))
                    res.append(s)
        return res
    shapes=cc(R,0); holes=zcomps(L)
    shapes.sort(key=lambda s:(max(a for a,b in s)-min(a for a,b in s)+1)*(max(b for a,b in s)-min(b for a,b in s)+1), reverse=True)
    holes.sort(key=len, reverse=True)
    out=[r[:] for r in L]
    for s in shapes:
        rs=[a for a,b in s]; cs=[b for a,b in s]
        hr=max(rs)-min(rs)+1; hw=max(cs)-min(cs)+1
        pat=[[R[min(rs)+a][min(cs)+b] if (min(rs)+a,min(cs)+b) in set(s) else 0 for b in range(hw)] for a in range(hr)]
        hi=min(a for a,b in holes[0]); ji=min(b for a,b in holes[0])
        for a in range(hr):
            for b in range(hw):
                if pat[a][b]:
                    out[hi+a][ji+b]=pat[a][b]
        holes.pop(0)
    return out
out=f(inp)
print('demo ok:', out==o)
res=f(G['Test input'])
for r in res: print(r)
