def pockets(g, wrap=False):
    n=len(g); m=len(g[0]); bg=None
    # background = most common color
    from collections import Counter
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=set(); out=[]
    for i in range(n):
        for j in range(m):
            if g[i][j]!=bg and (i,j) not in seen: continue
            s=[(i,j)]; st=[(i,j)]; seen.add((i,j))
            hit=False
            while st:
                a,b=st.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+dx,b+dy
                    nb2=(nb+nb%(m))%m if wrap else nb
                    na2=(na+1)%n if wrap else na
                    if (not wrap) and (na<n and nb<m) and g[na2][nb2]==bg and (na2,nb2) not in seen:
                        seen.add((na2,nb2)); s.append((na2,nb2))
                    elif wrap:
                        pass
                if a==0 or a==n-1 or b==0 or b==m-1: hit=True
            if not hit: out.append(s)
    return out
