def comps(g, val):
    seen=set(); res=[]; h=len(g); w=len(g[0])
    for i in range(h):
        for j in range(w):
            if g[i][j]==val and (i,j) not in seen:
                s=[(i,j)];st=[(i,j)];seen.add((i,j))
                while st:
                    a,b=st.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==val and (na,nb) not in seen:
